function fixture(alterar?:(u:URL,o:RequestInit|undefined)=>Response|Promise<Response>|undefined){
 let versaoAgente=1,modeloAgente='claude-fixture';const recibosAgente=new Map<string,number>();
 const buscar=vi.fn<typeof fetch>(async(entrada,o)=>{const u=new URL(String(entrada),'https://ficticio.invalid'),r=alterar?.(u,o);if(r)return r;const p=u.pathname.replace('/api/atendimento/operacao','');
  if(p==='/sessao')return json({usuario:{id:'usuario-ficticio',nome:'Pessoa de teste',perfilId:'perfil-ficticio',permissoes:LISTA_CAPACIDADES_ATENDIMENTO},csrf:'csrf-ficticio',modo:'homologacao',escritasReais:false});
  if(p==='/status')return json({...estadoBase,woocommerce:estadoWoo});
  if(p==='/conversas')return json({registros:[conversa(a,'Conversa A fictícia'),conversa(b,'Conversa B fictícia')],mais:false,pagina:0});
  if(p==='/historico')return json({registros:[{id:mensagem,conversaId:u.searchParams.get('conversaId'),autor:'cliente',autorId:null,conteudo:'Histórico '+(u.searchParams.get('conversaId')===a?'A':'B'),tipo:'text',estado:'recebido',criadaEm:em,anexoId:contato,citadaId:null}],proxima:null,conversa:conversa(u.searchParams.get('conversaId')!,u.searchParams.get('conversaId')===a?'Conversa A fictícia':'Conversa B fictícia')});
  if(p==='/rascunho')return json(o?.method==='PUT'?{texto:JSON.parse(String(o.body)).texto,versao:1}:{texto:'',versao:0});
  if(p.endsWith('/abertura'))return json({registrada:true});
  if(p.includes('/acao'))return json({gravada:true});if(p==='/mensagens/envio')return json({id:mensagem,estado:'aceito_simulado'});
  if(p==='/configuracao')return json({versao:1,agente:{modo:'desligado',modelo:'modelo-fixture'},horarios:{inicio:'09:00',fim:'18:00',dias:[1,2,3,4,5]},automacoes:false,enviosReais:false});
  if(p==='/agente')return json({modo:'desligado',modelo:modeloAgente,maxTokens:500,equipeApoio:'fixture',limites:{maxChamadas:2,custoPorChamadaCentavos:2,maxCustoCentavos:4,maxDuracaoMs:10000,timeoutChamadaMs:5000},custoCentavosDia:0,autoridadeAutomatica:false,grupoExterno:'indisponivel',versao:versaoAgente,credenciais:{anthropic:true,woo:false,voz:false},enviosReais:false});
  if(p==='/agente/configurar'){const d=JSON.parse(String(o?.body));modeloAgente=d.conteudo.modelo;recibosAgente.set(d.idempotencia,++versaoAgente);return json({versao:versaoAgente});}
  if(p==='/agente/reconciliar'){const d=JSON.parse(String(o?.body)),versao=recibosAgente.get(d.pedido.idempotencia);return json({estado:versao?'confirmada':'nao_registrada',versao:versao??null});}
  if(p==='/agente/followup')return json({configuracao:{habilitado:false,minutos:60,texto:'Mensagem fictícia de acompanhamento'},versao:1,origem:'local'});
  if(p==='/equipe')return json({usuarios:[{id:'usuario-ficticio',nome:'Pessoa de teste'}],equipes:[{id:'equipe-ficticia',nome:'Equipe de teste'}]});
  if(p==='/modelos')return json({registros:[]});if(p==='/duvidas')return json({casos:[]});if(p==='/conhecimento')return json({candidatos:[]});
  if(p==='/contatos')return json({registros:[{id:contato,nome:'Contato fictício',telefone:'000-000',email:null,tags:['Fixture'],hubClienteId:null}],mais:false,pagina:0});
  if(p==='/agente/opcoes')return json({principal:'anthropic',provedores:[{id:'anthropic',nome:'Anthropic',configurado:true,disponivel:true,testado:false,modelos:[{id:'claude-fixture',nome:'Claude de teste',disponivel:true,testado:false}]},{id:'google',nome:'Google',configurado:false,disponivel:false,testado:false,modelos:[]},{id:'openai',nome:'OpenAI',configurado:false,disponivel:false,testado:false,modelos:[]}]});
  if(p==='/agente/skills')return json({conteudo:{skills:[{id:'catalogo',nome:'Catálogo',finalidade:'Consultar produtos disponíveis',escopo:['produto'],habilitada:true,ferramentas:['search_products'],versao:2,responsavelId:'responsavel-ficticio'}]},versao:4,versaoAgente:1});
  if(p==='/agente/tom')return json({conteudo:{nome:'Perfil fictício',persona:'Atender com clareza',formalidade:'equilibrada',conciso:true,emojis:'moderado',termosPreferidos:['Obrigada'],termosProibidos:[],exemplos:['Posso ajudar?']},versao:3,versaoAgente:1});
  throw Error('ENDPOINT_FIXTURE_INEXISTENTE:'+p);
 });return {buscar,cliente:criarClienteOperacao(buscar)};
}
