it.each([1674,1024,390])('mantém o controle do rodapé acessível em %d px, com expansão e menu móvel preservados',async(largura)=>{
 const filtrar=(regras:CSSRuleList):string=>Array.from(regras).map(regra=>{
  if(regra.type===CSSRule.STYLE_RULE)return regra.cssText;
  if(regra.type!==CSSRule.MEDIA_RULE)return '';
  const media=regra as CSSMediaRule,min=media.conditionText.match(/min-width:\s*(\d+)px/),max=media.conditionText.match(/max-width:\s*(\d+)px/);
  return (min||max)&&(!min||largura>=Number(min[1]))&&(!max||largura<=Number(max[1]))?filtrar(media.cssRules):'';
 }).join('\n');
 const css=['../../apps/atendimento/preview/preview.css','../../apps/atendimento-chat-consulta/consulta.css','../../apps/atendimento-chat-consulta/operacao.css'].map(caminho=>{
  const fonte=document.createElement('style');fonte.textContent=readFileSync(new URL(caminho,import.meta.url),'utf8');document.head.append(fonte);const regras=filtrar(fonte.sheet!.cssRules);fonte.remove();return regras;
 }).join('\n'),estilo=document.createElement('style');estilo.textContent=css;document.head.append(estilo);vi.stubGlobal('innerWidth',largura);
 try{
  const {cliente}=fixture(),{container}=render(<ChatOperacao cliente={cliente}/>);await waitFor(()=>expect(screen.getByRole('tab',{name:'Conversas'})).toBeTruthy());
  if(largura<800)fireEvent.click(screen.getByRole('button',{name:'Abrir menu'}));
  const controle=screen.getByRole('button',{name:largura<800?'Fechar menu':'Recolher menu'});expect(getComputedStyle(controle).display).toBe('inline-flex');expect(controle.closest('.menu-rodape')).toBeTruthy();
  if(largura>=800){
   const marca=container.querySelector('.marca>div')!;expect(getComputedStyle(marca).display).not.toBe('none');fireEvent.click(controle);const expandir=screen.getByRole('button',{name:'Expandir menu'});expect(getComputedStyle(expandir).display).toBe('inline-flex');expect(getComputedStyle(marca).display).toBe('none');fireEvent.click(expandir);expect(getComputedStyle(marca).display).not.toBe('none');expect(screen.getByRole('button',{name:'Recolher menu'})).toBeTruthy();
  }else{expect(container.querySelector('.menu-lateral.aberto')).toBeTruthy();fireEvent.click(controle);expect(container.querySelector('.menu-lateral.aberto')).toBeNull();}
 }finally{estilo.remove();vi.unstubAllGlobals();}
});
